-- ============================================================================
-- farmaGO — SEED DEMO: 50 productos Farmex + farmacia demo Guardia Vieja 80
-- ============================================================================
-- Archivo de CARGA MANUAL. Ejecutar desde Supabase Dashboard -> SQL Editor.
-- NO es migracion. No duplica datos (idempotente via ON CONFLICT).
-- Precios: catalogo publico Farmex (CLP). Disponibilidad/cantidades: SINTETICAS demo.
-- NO representa stock fisico real de Guardia Vieja 80.
-- No se crean active_ingredients ni medication_active_ingredients.
-- Coordenadas verificadas (ArcGIS + geocode.xyz) para 'Guardia Vieja 80, Providencia'.
-- ============================================================================

set search_path = public, extensions;

-- ----------------------------------------------------------------------------
-- 1) Farmacia demo Farmex (Guardia Vieja 80, Providencia)
-- ----------------------------------------------------------------------------
insert into public.pharmacies (name, chain, address, comuna, region, location, source, external_id, is_active)
values (
  'Farmex',
  'Farmex',
  'Guardia Vieja 80, Providencia, Santiago',
  'Providencia',
  'Región Metropolitana',
  st_setsrid(st_makepoint(-70.610585, -33.423330), 4326)::geography,
  'farmex_demo',
  'farmex-guardia-vieja-80',
  true
)
on conflict (source, external_id) do update set
  name        = excluded.name,
  chain       = excluded.chain,
  address     = excluded.address,
  comuna      = excluded.comuna,
  region      = excluded.region,
  location    = excluded.location,
  is_active   = excluded.is_active,
  updated_at  = now();

-- ----------------------------------------------------------------------------
-- 2) Medicamentos (50 productos Farmex, primer variant)
-- ----------------------------------------------------------------------------
insert into public.medications (name, source, external_id, description, presentation_unit, barcode)
values
  ('Disilden 100 mg x 20 comprimidos', 'farmex', '5988900438198', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $349 Cada comprimido contiene Sildenafil (como citrato) 100 mg. Indicación: Tratamiento de la disfunción eréctil. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-17848/25', 'comprimidos', NULL),
  ('Mirena 20 mcg / 24 h x 1 Dispositivo Intrauterino', 'farmex', '1440359743540', 'La cantidad a despachar será revisada por el químico farmacéutico según el tratamiento adecuado. Precio por producto fraccionado: $239.990 Composición: Cada unidad contiene: Levonorgestrel 20 mcg. Indicación: Anticonceptivo intrauterino. Menorragia idiopática. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-4298/20', 'Dispositivo Intrauterino', NULL),
  ('Disilden 100 mg x 10 comprimidos', 'farmex', '1629418684468', 'Solución Efectiva para la Disfunción Eréctil 💖 Recupera la confianza y mejora tu vida íntima con Disilden 100 mg en su presentación de 10 comprimidos de Laboratorio IPHSA . Este medicamento contiene Sildenafil, un inhibidor de la fosfodiesterasa tipo 5 (PDE5) que actúa facilitando el flujo sanguíneo hacia el pene. Esto permite lograr y mantener una erección adecuada en respuesta a la estimulación sexual, ofreciendo un tratamiento eficaz y de alta dosis para la disfunción eréctil, siempre bajo prescripción médica. Beneficios Clave Alta Dosis de Sildenafil: Formulación de 100 mg para casos que requieren una mayor respuesta terapéutica. Mejora la Función Eréctil: Ayuda a lograr y mantener una erección suficiente para la actividad sexual. Acción Rápida: Generalmente comienza a actuar entre 30 y 60 minutos después de su ingesta. Tratamiento Conveniente: Presentación de 10 comprimidos, ideal para tener disponible según la necesidad. Datos Esenciales Principio Activo: Sildenafil (como citrato) 100 mg por cada comprimido. Forma Farmacéutica: Comprimidos. Dosis por Forma Farmacéutica: Según indicación médica. Cantidad por Envase: 10 comprimidos. Laboratorio: IPHSA. Precio por Producto Fraccionado: $499 Condiciones de Almacenamiento Almacenar a temperatura ambiente (entre 15°C y 30°C). Proteger de la humedad. Mantener fuera del alcance de los niños. Nombre del Producto Disilden 100 mg x 10 comprimidos (Laboratorio IPHSA). Condición de Venta Venta con receta médica. Efectos Colaterales Como todo medicamento, puede causar efectos no deseados. Los más comunes pueden incluir: Dolor de cabeza. Enrojecimiento facial (rubor). Dispepsia (indigestión). Visión borrosa o alteración de la percepción de colores. Si experimenta una erección prolongada (más de 4 horas) o dolorosa, o pérdida súbita de la visión o audición, busque atención médica de urgencia inmediatamente. Contraindicaciones No uses si tienes hipersensibilidad conocida al Sildenafil. Absolutamente contraindicado si estás tomando medicamentos que contienen nitratos (como nitroglicerina) para el dolor de pecho, ya que puede causar una caída peligrosa de la presión arterial. No uses si tienes problemas cardiovasculares graves o si tu médico te ha desaconsejado la actividad sexual. Consulta a tu médico si tienes antecedentes de problemas de visión, renales o hepáticos. Notas Adicionales Uso recomendado: Indicado para el tratamiento de la disfunción eréctil en hombres adultos. Debe tomarse aproximadamente 1 hora antes de la actividad sexual y solo una vez al día. Importante: La estimulación sexual es necesaria para que Sildenafil sea efectivo.', 'comprimidos', NULL),
  ('Disilden 50 mg  x 20 comprimidos', 'farmex', '6589722984630', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $400 Cada comprimido contiene Sildenafil (como citrato) 50 mg. Indicación : Tratamiento de la disfunción eréctil. Uso en ancianos: Como el clearence de Disilden se reduce en estos pacientes, se debería utilizar una primera dosis de 25 mg. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-17847/24', 'comprimidos', NULL),
  ('Sayana Press 104 mg / 0.65 mL x 1 Suspension Inyectable "Ley Cenabast"', 'farmex', '7212279693494', 'Principio Activo: Medroxiprogesterona Acetato (DMPA) 104 mg / 0.65 mL por cada suspensión inyectable. Forma Farmacéutica: Suspensión Inyectable (Sistema de inyección prellenado). Dosis por Forma Farmacéutica: 104 mg / 0.65 mL. Cantidad por Envase: 1 suspensión inyectable. Laboratorio: PFIZER. Precio por Producto Fraccionado: $14.990 Condiciones de Almacenamiento Almacenar a temperatura ambiente controlada (entre 20°C y 25°C). Proteger de la luz. Mantener fuera del alcance de los niños. Nombre del Producto Sayana Press 104 mg / 0.65 mL x 1 Suspensión Inyectable "Ley Cenabast" (Laboratorio PFIZER). Condición de Venta Venta con receta médica. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: http://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-23721/18', 'Suspension Inyectable', NULL),
  ('Hyabak Gotas Oftálmicas x 10 mL', 'farmex', '1439943491636', 'Hyabak Gotas Oftálmicas x 10 mL | Solución Lubricante para Ojos Secos Descripción Hyabak Gotas Oftálmicas es una solución lubricante formulada con ácido hialurónico , diseñada para aliviar los síntomas asociados con el ojo seco. Su fórmula avanzada proporciona hidratación intensa y duradera, restaurando la comodidad ocular y protegiendo la superficie del ojo contra irritaciones causadas por factores ambientales como el uso prolongado de pantallas, aire acondicionado o contaminación. Ideal para quienes buscan una solución efectiva y segura para cuidar sus ojos. Ficha Técnica Principio Activo : Ácido hialurónico al 0,15%. Forma Farmacéutica/Cosmética : Solución oftálmica estéril. Dosis por Aplicación : Una gota en cada ojo según necesidad. Cantidad por Envase : Frasco multidosis de 10 mL (aproximadamente 300 gotas). Presentación : Frasco ergonómico con sistema de conservación estéril para múltiples usos. Condiciones de almacenamiento : Almacenar a temperatura ambiente (entre 15°C y 25°C). No exponga a temperaturas extremas o luz solar directa. Mantenga fuera del alcance de los niños. Posología Dosis Recomendada : Aplicar 1 gota en cada ojo tantas veces como sea necesario, especialmente cuando sienta sequedad, irritación o fatiga ocular. Modo de administración : Lávese bien las manos antes de usar el producto. Incline la cabeza hacia atrás, abra suavemente el ojo y aplique 1 gota en el ojo afectado. Parpadee suavemente para distribuir la solución uniformemente. Duración del Tratamiento : Úselo según necesidad para aliviar los síntomas de ojos secos. Si los síntomas persisten o empeoran, consulte a un oftalmólogo. Beneficios principales Descubra por qué Hyabak Gotas Oftálmicas es una solución confiable para el cuidado de los ojos: Hidratación Prolongada : El ácido hialurónico proporciona una película protectora que mantiene los ojos hidratados durante horas. Protección Ocular : Forma una barrera natural sobre la superficie del ojo, reduciendo la irritación causada por factores ambientales como viento, aire acondicionado o pantallas digitales. Alivio Inmediato : Restaura la comodidad ocular rápidamente, eliminando la sensación de arenilla o ardor. Fácil de Usar : Presentación en frasco multidosis con sistema estéril, ideal para uso diario y portátil. Seguro y Compatible : Libre de conservantes agresivos, lo que reduce el riesgo de reacciones alérgicas o irritaciones adicionales. Contraindicaciones Aunque Hyabak Gotas Oftálmicas es seguro cuando se usa correctamente, ten en cuenta lo siguiente: Alergia o Hipersensibilidad : No uso si tiene alergia conocida al ácido hialurónico u otros componentes del producto. Uso Exclusivo Oftálmico : Este producto está diseñado únicamente para uso en los ojos. No debe ingerirse ni aplicarse en otras áreas. Embarazo y Lactancia : Consulte a su médico antes de usarlo para garantizar su seguridad. Niños Pequeños : Este producto está formulado principalmente para adultos. No es recomendable para menores sin supervisión médica. Efectos secundarios comunes : Irritación leve o visión borrosa temporal después de la aplicación. En casos raros, puede causar reacciones alérgicas locales. Si experimenta síntomas graves, suspenda el uso y consulte a un oftalmólogo. ¿Por Qué Elegir Hyabak Gotas Oftálmicas? Resultados Clínicos : Fórmula respaldada por estudios científicos que demuestran su eficacia en el tratamiento del ojo seco. Hidratación Duradera : Proporciona alivio prolongado gracias a su innovadora combinación de ingredientes activos. Facilidad de Uso : Presentación en frasco multidosis estéril, ideales para un uso práctico y seguro. Confianza Garantizada : Producto ampliamente recomendado por oftalmólogos para el cuidado de los ojos secos. Comprar ahora Encuentra Hyabak Gotas Oftálmicas x 10 mL exclusivamente en Farmex, Precios bajos a tu casa , tu farmacia de confianza.', 'mL', NULL),
  ('Tadalafilo 20 mg x 4 comprimidos', 'farmex', '7364527095990', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $2.498 Cada comprimido recubierto contiene: 20 mg de Tadalafilo. Indicación: Tratamiento de la disfunción eréctil. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-22182/20', 'comprimidos', NULL),
  ('Ozempic Solución Inyectable 2 mg / 1,5 mL x 1 dispositivo', 'farmex', '7602985730230', 'Este medicamento es refrigerado, el despacho gratis no aplica y solo está disponible en las siguientes comunas: MAIPÚ, CONCHALI, ESTACION CE NTRAL, HUECHURABA, INDEPENDENCIA, LA CISTERNA, LA GRANJA, LA FLORIDA, LA REINA, LAS CONDES, LO PRADO, MACUL, NUNOA, PEDRO AGUIRRE CERDA, PENALOLEN, PROVIDENCIA, QUINTA NORMAL, RECOLETA, SAN MIGUEL, SAN JOAQUIN, SANTIAGO, VITACURA y LO BARNECHEA. También está disponible para entrega en nuestra farmacia ubicada en: Padre Hurtado Central 1531, local 4A, Las Condes. La cantidad a despachar será revisada por el químico farmacéutico según el tratamiento adecuado. Precio por producto fraccionado: $188.990 Cada ml de solución contiene: 1,34 mg de semaglutida. Conservación: Condiciones de almacenamiento y vida útil envase cerrado: Conservar en refrigeración (entre 2° C y 8° C). No congelar. 36 meses. Condiciones de almacenamiento y vida útil después del primer uso: Conservar por debajo de 30° C o en refrigeración. No congelar. Mantenga el dispositivo con la tapa colocada para protegerlo de la luz. Deseche el dispositivo 6 semanas después de su primer uso. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=B-2774/19 Este medicamento no tiene servicio de traslado con Shipex Express, si desea concretar su recibo, lo puede hacer a través de Shipex o retirarlo en nuestra sucursal. Nota: Para este medicamento de alto valor no será válido ningún cupón de descuento, aunque por sistema se reflejan dichos descuentos. Si el usuario utiliza algún cupón, el equipo de servicio al cliente lo contactará posteriormente para confirmar si quiere pagar la diferencia o anular la compra.', 'dispositivo', NULL),
  ('Paracetamol 500 mg x 16 comprimidos', 'farmex', '1439945687092', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $49 Cada comprimido contiene 500 mg de paracetamol Indicaciones: Tratamientos sintomáticos de estados dolorosos y febriles, dolor de cabeza, musculares y dentales; alivia malestares de la gripe, resfríos y lumbago. Intolerancia a salicilatos. Posología: Adultos: 1-4 g/día cada 4-6 horas (dosis máxima 4 g/día). Contraindicaciones: Hipersensibilidad al paracetamol. Insuficiencia hepática. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-4001/20', 'comprimidos', NULL),
  ('Losartan Potásico 50 mg x 30 comprimidos', 'farmex', '1439929598004', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $43 Cada comprimido recubierto contiene: Losartán Potásico 50 mg. Indicación: Tratamiento de la hipertensión arterial. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-13738/24', 'comprimidos', NULL),
  ('Engystol x 50 comprimidos', 'farmex', '1439943327796', 'Engystol es un medicamento homeopático que ayuda a estimular las defensas naturales del cuerpo, especialmente durante infecciones virales como resfriados, gripes o procesos febriles. Su fórmula combina ingredientes activos como sulfuro de calcio y fosfato tricálcico, promoviendo una respuesta inmunológica más rápida y eficiente. Ideal para quienes buscan prevenir o aliviar síntomas asociados con infecciones recurrentes. INFORMACIÓN TÉCNICA Principios Activos : Sulfuro de calcio (Calcium sulfuricum), Fosfato tricálcico (Calcium phosphoricum), entre otros. Forma Farmacéutica : Comprimidos sublinguales. Dosis por Aplicación : Dejar disolver 1-2 comprimidos bajo la lengua 3 veces al día o según indicación médica. Cantidad por envase : 50 comprimidos. Presentación (Forma Farmacéutica y Dosis): Este producto tiene una presentación en formato de comprimidos sublinguales, diseñados para disolverse rápidamente bajo la lengua. Cada envase contiene 50 comprimidos, proporcionando múltiples dosis para apoyar el sistema inmunológico durante episodios de infecciones virales. CONDICIONES DE ALMACENAMIENTO Almacenar a temperatura ambiente (entre 15°C y 25°C). Mantener en un lugar seco y protegido de la luz solar directa. Cerrar bien el envase después de cada uso. Mantener lejos del alcance de los niños. Nombre del Producto : Engystol. Condición de Venta : Venta libre. NOTAS ADICIONALES Uso recomendado : Dejar disolver 1-2 comprimidos bajo la lengua 3 veces al día, preferiblemente lejos de las comidas. Aumentar la frecuencia si es necesario durante episodios agudos. Importante : No exceder la dosis recomendada. Consulte a su médico antes de usarlo si está embarazada, lactando o tomando otros medicamentos. EFECTOS COLATERALES Engystol generalmente es bien tolerado cuando se usa correctamente. Sin embargo, pueden ocurrir reacciones adversas muy raras como: Reacciones alérgicas locales (picazón o enrojecimiento en la boca). Sensación de hormigueo leve tras la disolución. Si experimenta algún síntoma persistente o grave, suspenda el uso y consulte a su médico. BENEFICIOS PRINCIPALES Engystol ofrece múltiples beneficios para el sistema inmunológico y el manejo de infecciones virales: Estimulación de las defensas naturales : Ayuda al cuerpo a combatir infecciones virales más rápidamente. Alivio de síntomas : Reduce fiebre, malestar general y congestión asociados con resfriados y gripes. Prevención de recurrencias : Fortalece el sistema inmunológico para reducir episodios repetitivos de infecciones. Fácil administración : Comprimidos sublinguales permiten una absorción rápida y eficiente. Solución natural : Ingredientes homeopáticos ideales para quienes prefieren alternativas no convencionales.', 'comprimidos', NULL),
  ('Thealoz Duo Gotas Oftámicas x 10 mL', 'farmex', '4453884002384', 'Thealoz Duo es un lubricante oftálmico indicado para aliviar la sequedad ocular y proteger la superficie del ojo. Su fórmula combina ácido hialurónico y taurina, proporcionando hidratación intensa y reparación celular. Ideal para personas con ojos secos, irritados o fatigados por el uso prolongado de pantallas, lentes de contacto o condiciones ambientales adversas. INFORMACIÓN TÉCNICA Principio Activo : Ácido hialurónico + Trehalosa Forma Farmacéutica : Solución oftálmica estéril Dosis por Aplicación : 1-2 gotas por ojo según necesidad Cantidad por envase : 10 mL Presentación (Forma Farmacéutica y Dosis): Este producto tiene una presentación en formato de solución oftálmica estéril, con una combinación única de ácido hialurónico y taurina. Cada envase contiene 10 mL, suficiente para múltiples aplicaciones diarias durante varias semanas. CONDICIONES DE ALMACENAMIENTO Almacenar a temperatura ambiente (entre 2°C y 25°C). Mantener el envase bien cerrado después de cada uso. No exponer directamente a la luz solar. Evitar el contacto del aplicador con cualquier superficie para mantener la esterilidad. Mantener lejos del alcance de los niños. Nombre del Producto : Thealoz Duo Gotas Oftálmicas. Condición de Venta : Venta libre. NOTAS ADICIONALES Uso recomendado : Aplicar 1-2 gotas en cada ojo según necesidad, especialmente cuando sienta sequedad, irritación o fatiga ocular. Importante : No utilizar si el sello de seguridad está roto. Consulte a su médico si experimenta síntomas persistentes o si usa lentes de contacto blandas/híbridas. EFECTOS COLATERALES Thealoz Duo generalmente es bien tolerado cuando se usa correctamente. Sin embargo, pueden ocurrir reacciones adversas locales como: Ligera irritación o ardor temporal tras la aplicación. Enrojecimiento leve en casos sensibles. Visión borrosa momentánea después de la aplicación. Si experimenta algún síntoma persistente o grave, suspenda el uso y consulte a su médico. BENEFICIOS PRINCIPALES Thealoz Duo ofrece múltiples beneficios para el cuidado de los ojos: Hidratación intensa : El ácido hialurónico retiene la humedad en la superficie ocular, aliviando la sequedad. Reparación celular : La taurina promueve la regeneración de las células dañadas en la córnea. Protección duradera : Forma una barrera protectora que reduce la irritación causada por factores externos. Fácil de usar : Diseñado para aplicaciones rápidas y cómodas, incluso durante el uso de lentes de contacto. Compatibilidad segura : Fórmula estéril y sin conservantes perjudiciales.', 'mL', NULL),
  ('Disilden 50 mg x 10 comprimidos', 'farmex', '4433887068240', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $499 Cada comprimido contiene Sildenafil (como citrato) 50 mg. Indicación: Tratamiento de la disfunción eréctil. Uso en ancianos: Como el clearence de Disilden se reduce en estos pacientes, se debería utilizar una primera dosis de 25 mg. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-17847/24', 'comprimidos', NULL),
  ('Kyleena 19,5 mg Sistema Intrauterino', 'farmex', '7430144196790', 'Anticonceptivo Hormonal de Larga Duración Kyleena 19,5 mg es un sistema intrauterino (SIU) que contiene Levonorgestrel , un progestágeno sintético. Está diseñado para proporcionar una anticoncepción altamente efectiva durante un período de hasta 5 años mediante la liberación continua y controlada de la hormona en el útero. Además de su función anticonceptiva, Kyleena puede ayudar a reducir el sangrado menstrual y los cólicos menstruales en algunas mujeres. Ideal para quienes buscan una solución anticonceptiva de larga duración, reversible y mínimamente invasiva. INFORMACIÓN TÉCNICA Principio Activo : Levonorgestrel 19,5 mg. Forma Farmacéutica : Sistema intrauterino (SIU). Dosis por Forma Farmacéutica : Liberación diaria de aproximadamente 8 microgramos de Levonorgestrel. Cantidad por Envase : 1 sistema intrauterino. Duración de Efectividad : Hasta 5 años. Precio por producto fraccionado : $314.990. Condiciones de Almacenamiento Almacenar a temperatura ambiente (entre 15°C y 30°C). Proteger de la luz solar directa y la humedad. Mantener fuera del alcance de los niños. Nombre del Producto Kyleena 19,5 mg Sistema Intrauterino. Condición de Venta Venta con receta médica retenida.', 'Sistema Intrauterino', NULL),
  ('Ozempic solución inyectable 4 mg/3 mL x 1 jeringa precargada (1 mg x dosis)', 'farmex', '7904041697462', 'Este medicamento es refrigerado, el despacho gratis no aplica y solo está disponible en las siguientes comunas: MAIPÚ, CONCHALI, ESTACION CE NTRAL, HUECHURABA, INDEPENDENCIA, LA CISTERNA, LA GRANJA, LA FLORIDA, LA REINA, LAS CONDES, LO PRADO, MACUL, NUNOA, PEDRO AGUIRRE CERDA, PENALOLEN, PROVIDENCIA, QUINTA NORMAL, RECOLETA, SAN MIGUEL, SAN JOAQUIN, SANTIAGO, VITACURA y LO BARNECHEA. También está disponible para entrega en nuestra farmacia ubicada en: Padre Hurtado Central 1531, local 4A, Las Condes. La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $279.990 Cada mL de solución contiene: 1.33 mg de Semaglutida. Conservación: Condiciones de almacenamiento y vida útil envase cerrado: Conservar en refrigeración (entre 2° C y 8° C). No congelar. 36 meses. Condiciones de almacenamiento y vida útil después del primer uso: Conservar por debajo de 30° C o en refrigeración. No congelar. Mantenga el dispositivo con la tapa colocada para protegerlo de la luz. Deseche el dispositivo 6 semanas después de su primer uso. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=B-2993/23 Nota: Para este medicamento de alto valor no será válido ningún cupón de descuento, aunque por sistema se reflejan dichos descuentos. Si el usuario utiliza algún cupón, el equipo de servicio al cliente lo contactará posteriormente para confirmar si quiere pagar la diferencia o anular la compra.', 'jeringa precargada', NULL),
  ('Taldus 5 mg x 30 comprimidos', 'farmex', '6616094113974', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $1.283 Cada comprimido recubierto contiene: Tadalafilo 5 mg. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: http://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-23456/17', 'comprimidos', NULL),
  ('Ibuprofeno 600 mg Lab chile - 20 Comprimidos', 'farmex', '1590627074100', 'Alivio Rápido para el Dolor, la Inflamación y la Fiebre 🌡️ Descubre una solución confiable desarrollada por Laboratorio Chile para combatir el dolor, reducir la inflamación y bajar la fiebre. Con Ibuprofeno 600 mg , este medicamento actúa como un antiinflamatorio no esteroideo (AINE), brindando alivio efectivo para condiciones como artritis, dismenorrea, dolores musculares y estados febriles. Ideal para quienes buscan un tratamiento accesible y eficaz bajo supervisión médica. INFORMACIÓN TÉCNICA Principio Activo : Ibuprofeno 600 mg. Forma Farmacéutica : Comprimidos recubiertos. Dosis por Forma Farmacéutica : Según indicación médica. Cantidad por Envase : 20 comprimidos. Condiciones de Almacenamiento Almacenar a temperatura ambiente (entre 15°C y 25°C). Proteger de la luz solar directa y la humedad. Mantener fuera del alcance de los niños. Nombre del Producto Ibuprofeno 600 mg x 20 comprimidos (Laboratorio Chile). Condición de Venta Venta con receta médica retenida. Notas Adicionales Uso recomendado : Estados Inflamatorios Dolorosos : La dosis será determinada por tu médico, generalmente cada 6-8 horas según necesidad. Fiebre : Administrar según indicación médica para reducir la temperatura corporal. Dismenorrea : Eficaz para aliviar el dolor menstrual asociado con inflamación. Artritis Reumatoide y Osteoartritis : Reduce los síntomas y mejora la movilidad articular. Modo de Administración : Tragar el comprimido entero con agua. No masticar ni triturar. Puede tomarse con alimentos para reducir molestias estomacales. Importante : Este producto debe usarse bajo supervisión médica estricta. No exceder la dosis recomendada ni prolongar el tratamiento sin consulta previa. Efectos Colaterales Generalmente bien tolerado, pero pueden ocurrir efectos adversos como: Dolor de estómago, náuseas o malestar digestivo. Mareos o somnolencia. En casos raros, úlceras estomacales o reacciones alérgicas graves. Si experimentas algún síntoma persistente o grave, suspende el uso y consulta inmediatamente a tu médico. Beneficios Clave Este medicamento ofrece múltiples ventajas para el manejo del dolor y la inflamación: Acción Antiinflamatoria y Analgésica : Reduce el dolor y la inflamación de manera efectiva. Control de la Fiebre : Ideal para bajar la temperatura corporal en estados febriles. Alivio para la Dismenorrea : Ayuda a manejar el dolor menstrual asociado con inflamación. Tratamiento de Artritis : Mejora los síntomas de artritis reumatoide y osteoartritis, promoviendo mayor movilidad. Fácil de Usar : Presentación en comprimidos recubiertos de fácil administración, diseñados para integrarse en tu rutina diaria. Contraindicaciones No use si tiene hipersensibilidad conocida al Ibuprofeno u otros AINEs. Evite su uso si tiene antecedentes de úlcera péptica, insuficiencia renal o hepática sin consulta médica previa. Consulte a su médico antes de usarlo si está embarazada, lactando o tomando anticoagulantes.', 'Comprimidos', NULL),
  ('Vimax  50 mg x 6 comprimidos', 'farmex', '1439932088372', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $1.931 Cada comprimido masticable contiene: Sildenafil (como Citrato) 50 mg. Indicación: Tratamiento de la disfunción eréctil. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-27043/22', 'comprimidos', NULL),
  ('Melatonina 3 mg x 30 cápsulas', 'farmex', '1439949750324', 'Apoyo Natural para un Descanso Reparador 😴 Si buscas una ayuda natural para conciliar el sueño y mejorar la calidad de tu descanso, las Cápsulas de Melatonina 3 mg x 30 de Laboratorio ARAMA son una excelente opción. Este suplemento está diseñado para apoyar el ciclo natural de sueño-vigilia de tu cuerpo, ayudándote a regular tus patrones de sueño, especialmente útil si experimentas dificultades para dormir, jet lag o turnos de trabajo irregulares. Despierta renovado y con energía para tu día. Beneficios Clave Favorece el Sueño Natural: Ayuda a tu cuerpo a regular su ritmo circadiano, facilitando la conciliación del sueño. Mejora la Calidad del Descanso: Contribuye a un sueño más profundo y reparador, para que te sientas más descansado. Alivia el Jet Lag: Ideal para ajustar tu reloj biológico al viajar a través de diferentes zonas horarias. Fácil de Incorporar: Cápsulas convenientes para integrar en tu rutina nocturna. Información Técnica Principio Activo: Melatonina 3 mg por cada cápsula. Forma Farmacéutica: Cápsulas. Dosis por Forma Farmacéutica: Según indicación. Cantidad por Envase: 30 cápsulas. Laboratorio: ARAMA. Precio por Producto Fraccionado: $133 Condiciones de Almacenamiento Almacenar en un lugar fresco y seco, a temperatura ambiente. Proteger de la luz solar directa. Mantener fuera del alcance de los niños. Nombre del Producto Melatonina 3 mg x 30 cápsulas (Laboratorio ARAMA). Condición de Venta Venta libre. Efectos Colaterales La Melatonina es generalmente bien tolerada. Sin embargo, algunas personas podrían experimentar: Somnolencia diurna (si se toma demasiado tarde o en dosis altas). Dolor de cabeza. Mareos. Náuseas. Si experimentas cualquier efecto adverso persistente o preocupante, consulta a un profesional de la salud. Contraindicaciones No uses si tienes hipersensibilidad conocida a la Melatonina o a cualquier componente del producto. Consulta a tu médico antes de usar si estás embarazada, en período de lactancia, o si tienes alguna enfermedad autoinmune, depresión, epilepsia, problemas hepáticos o renales. Evita manejar maquinaria pesada o conducir después de tomar melatonina, ya que puede causar somnolencia. Notas Adicionales Uso recomendado: Para adultos con dificultades para conciliar el sueño o para regular el ritmo circadiano. La dosis y el momento de la toma pueden variar según la necesidad individual y la recomendación de un profesional de la salud. Generalmente se toma poco antes de acostarse. Importante: Este es un suplemento alimenticio. No reemplaza una dieta equilibrada. Si estás bajo medicación o tienes alguna condición de salud preexistente, consulta a tu médico antes de iniciar su uso.', 'cápsulas', NULL),
  ('Piascledine x 30 cápsulas', 'farmex', '1439944802356', '¿Qué es Piascledine? Piascledine es un medicamento a base de Persea gratissima y Glycine max , utilizado como tratamiento complementario en enfermedades articulares degenerativas como la osteoartritis. Usos y Beneficios de Piascledine Alivia los síntomas de la osteoartritis y otras enfermedades articulares. Contribuye a la protección y regeneración del cartílago. Ayuda a reducir la inflamación y el dolor en las articulaciones. Mejora la movilidad articular en pacientes con desgaste del cartílago. Alternativa natural con menor impacto en el sistema gastrointestinal en comparación con los AINEs. Precauciones y Contraindicaciones de Piascledine No indicado en personas con alergia a la soja o al aguacate. Debe usarse con precaución en personas con trastornos hepáticos. No recomendado durante el embarazo o la lactancia sin supervisión médica. Consultar con un médico antes de su uso en combinación con otros tratamientos para la osteoartritis. Posibles Efectos Secundarios de Piascledine Molestias gastrointestinales leves como náuseas o diarrea. Reacciones alérgicas en personas sensibles a sus componentes. En casos raros, dolor abdominal o erupciones cutáneas.', 'cápsulas', NULL),
  ('Prolopa 200 mg / 50 mg x 30 comprimidos "Ley Cenabast"', 'farmex', '1439946080308', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $390 Cada cápsula contiene: Levodopa 200 mg; Benserazida 50 mg Indicación: Tratamiento de la enfermedad de Parkinson. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-4169/20', 'comprimidos', NULL),
  ('Alopek Espuma Tópica 5% x 100 g (Minoxidil)', 'farmex', '4173617102900', 'Alopek Espuma Tópica es un tratamiento eficaz contra la alopecia androgénica en hombres. Su fórmula con minoxidil al 5% estimula el crecimiento del cabello, aumentando el flujo sanguíneo hacia los folículos pilosos. Ideal para quienes buscan una solución práctica y efectiva para combatir la caída del cabello y promover una cabellera más densa y saludable. INFORMACIÓN TÉCNICA Principio Activo : Minoxidil 5% Forma Farmacéutica : Espuma tópica Dosis por Aplicación : 1 aplicación (media tapa de espuma) dos veces al día Cantidad por envase : 100 g Presentación (Forma Farmacéutica y Dosis): Este producto tiene una presentación en formato de espuma tópica, con una concentración de minoxidil al 5%. Cada envase contiene 100 g, suficiente para múltiples aplicaciones diarias durante varias semanas, facilitando su uso en el cuero cabelludo. CONDICIONES DE ALMACENAMIENTO Almacenar a temperatura ambiente (entre 15°C y 25°C). Mantener en un lugar seco y protegido de la luz solar directa. No perforar ni exponer el envase a altas temperaturas o llamas. Cerrar bien el envase después de cada uso. Mantener lejos del alcance de los niños. Nombre del Producto : Alopek Espuma Tópica 5%. Condición de Venta : Venta libre. NOTAS ADICIONALES Uso recomendado : Aplicar media tapa de espuma sobre el cuero cabelludo limpio y seco, dos veces al día (mañana y noche). Masajear suavemente hasta su absorción. Importante : No utilizar en áreas dañadas o irritadas de la piel. Consulte a su médico si experimenta reacciones adversas o si no observa resultados después de 3 meses de uso continuo. EFECTOS COLATERALES Alopek Espuma Tópica generalmente es bien tolerada cuando se usa correctamente. Sin embargo, pueden ocurrir reacciones adversas locales como: Irritación, picazón o sequedad en el cuero cabelludo. Enrojecimiento o descamación leve. Sensación de ardor temporal tras la aplicación. En casos raros, aumento de la caída inicial del cabello antes de su regeneración. Si experimenta algún síntoma persistente o grave, suspenda el uso y consulte a su médico. BENEFICIOS PRINCIPALES Alopek Espuma Tópica ofrece múltiples beneficios para el tratamiento de la alopecia androgénica: Estimulación del crecimiento capilar : El minoxidil activa los folículos pilosos inactivos, promoviendo el crecimiento de nuevo cabello. Facilidad de uso : Su formato en espuma permite una aplicación rápida, cómoda y sin residuos grasos. Mejora la densidad capilar : Incrementa el grosor y volumen del cabello con el uso continuo. Fórmula ligera : No deja sensación pegajosa y se absorbe rápidamente. Resultados visibles : Mejora gradualmente la apariencia del cabello en unas semanas de uso constante.', 'g', NULL),
  ('Celecoxib 200 mg: 30 Cápsulas Antiinflamatorias', 'farmex', '3669858123828', 'Alivio Duradero para el Dolor y la Inflamación con Celecoxib 200 mg 🌟 Descubre una solución avanzada desarrollada por Laboratorio Synthon para el manejo del dolor y la inflamación. Con Celecoxib 200 mg , este medicamento actúa como un inhibidor selectivo de COX-2, reduciendo el dolor y la inflamación sin comprometer significativamente el estómago. Ideal para adultos que buscan alivio efectivo en condiciones como osteoartritis, artritis reumatoide, espondilitis anquilosante, dolor agudo y dismenorrea primaria. INFORMACIÓN TÉCNICA Principio Activo : Celecoxib 200 mg. Forma Farmacéutica : Cápsulas de gelatina dura. Dosis por Forma Farmacéutica : 1 cápsula (según indicación médica). Cantidad por Envase : 30 cápsulas. Condiciones de Almacenamiento Almacenar a no más de 25°C. Mantener en un lugar seguro y seco. Evitar la exposición directa a la luz solar. Mantener fuera del alcance de los niños. Nombre del Producto Celecoxib 200 mg x 30 cápsulas (Laboratorio Synthon). Condición de Venta Venta con receta médica retenida. Notas Adicionales Uso recomendado : Osteoartritis : 200 mg una vez al día ó 100 mg dos veces al día. Artritis Reumatoide : 100 mg ó 200 mg dos veces al día. Espondilitis Anquilosante : La dosis será determinada por tu médico. Dolor Agudo o Dismenorrea Primaria : Según severidad del dolor. Modo de Administración : Tragar la cápsula entera con agua. No masticar ni triturar. Puede tomarse con o sin alimentos, aunque consumirlo con alimentos puede reducir molestias estomacales. Importante : Este producto debe usarse bajo supervisión médica estricta. No exceda la dosis recomendada y complete el tratamiento según las indicaciones de su médico. Efectos Colaterales Generalmente bien tolerado, pero pueden ocurrir efectos adversos como: Dolor de cabeza, mareos o somnolencia. Náuseas, diarrea o malestar estomacal. En casos raros, reacciones graves como hemorragia gastrointestinal, eventos cardiovasculares o daño hepático. Si experimentas algún síntoma persistente o grave, suspende el uso y consulta inmediatamente a tu médico. Beneficios Clave Este medicamento ofrece múltiples ventajas para el manejo del dolor y la inflamación: Acción Selectiva sobre COX-2 : Reduce el riesgo de efectos adversos gastrointestinales en comparación con otros AINEs. Alivio Eficaz del Dolor : Ideal para condiciones crónicas como osteoartritis y artritis reumatoide. Versatilidad Terapéutica : Eficaz para dolor agudo, espondilitis anquilosante y dismenorrea primaria. Confianza Synthon : Desarrollado por un laboratorio reconocido por su enfoque en soluciones modernas y accesibles. Fácil Administración : Una vez al día o dividido en dos tomas según la condición tratada. Contraindicaciones No use si tiene hipersensibilidad conocida al Celecoxib u otros inhibidores de COX-2. Evite su uso si tiene antecedentes de enfermedades cardiovasculares severas, insuficiencia hepática o renal sin consulta médica previa. Consulte a su médico antes de usarlo si está embarazada, lactando o tomando anticoagulantes.', 'Cápsulas Antiinflamatorias', NULL),
  ('Ripol 100 mg x 10 comprimidos', 'farmex', '7624327594166', 'Solución Efectiva para la Disfunción Eréctil Ripol 100 mg es un medicamento que contiene Sildenafil , un inhibidor selectivo de la fosfodiesterasa tipo 5 (PDE-5). Está diseñado para el tratamiento de la disfunción eréctil (DE), ayudando a lograr y mantener una erección adecuada durante la estimulación sexual. Actúa aumentando el flujo sanguíneo hacia el pene, lo que permite una respuesta natural y efectiva al estímulo sexual. Ideal para hombres que buscan una solución confiable y probada para mejorar su función eréctil. INFORMACIÓN TÉCNICA Principio Activo : Sildenafil 100 mg. Forma Farmacéutica : Comprimidos. Dosis por Forma Farmacéutica : 1 comprimido. Cantidad por Envase : 10 comprimidos. Precio por producto fraccionado : $499. Condiciones de Almacenamiento Almacenar a temperatura ambiente (entre 15°C y 25°C). Proteger de la luz solar directa y la humedad. Mantener fuera del alcance de los niños. Nombre del Producto Ripol 100 mg x 10 comprimidos. Condición de Venta Venta con receta médica retenida. Notas Adicionales Uso recomendado : Tomar 1 comprimido aproximadamente 30-60 minutos antes de la actividad sexual, según indicación médica. La dosis máxima recomendada es de 1 comprimido por día. No debe exceder esta dosis bajo ninguna circunstancia. Modo de Administración : Tragar el comprimido entero con agua. Puede tomarse con o sin alimentos, aunque los alimentos altos en grasa pueden retrasar su efecto. Importante : Este producto requiere estimulación sexual para ser efectivo. No actúa como afrodisíaco ni aumenta el deseo sexual. No use este medicamento si está tomando nitratos o donadores de óxido nítrico, ya que puede causar una caída peligrosa de la presión arterial. Efectos Colaterales Generalmente bien tolerado, pero pueden ocurrir efectos adversos como: Dolor de cabeza, mareos o rubor facial. Congestión nasal, indigestión o malestar estomacal. Visión borrosa o alteraciones visuales transitorias (como visión azulada). En casos raros, priapismo (erección dolorosa prolongada) o problemas cardíacos graves. Si experimenta algún síntoma persistente o grave, suspenda el uso y consulte inmediatamente a su médico. Beneficios Principales Ripol 100 mg ofrece múltiples beneficios para el tratamiento de la disfunción eréctil: Erecciones Naturales y Efectivas : Facilita una respuesta eréctil adecuada durante la estimulación sexual. Acción Rápida : Comienza a actuar en aproximadamente 30-60 minutos y su efecto puede durar hasta 4-6 horas. Confianza Restaurada : Ayuda a mejorar la autoestima y la calidad de las relaciones íntimas. Fácil de Usar : Presentación en comprimidos de fácil administración, ideal para uso ocasional. Contraindicaciones No use si tiene hipersensibilidad conocida al Sildenafil o cualquiera de los componentes del producto. Evite su uso si está tomando nitratos o donadores de óxido nítrico debido al riesgo de interacciones graves. Consulte a su médico antes de usarlo si tiene antecedentes de enfermedades cardiovasculares, hepáticas, renales o retinitis pigmentosa. No administrar en menores de edad o mujeres.', 'comprimidos', NULL),
  ('Pasurta 140 mg / 1 mL Solución Inyectable Jeringa Precargada', 'farmex', '6979342270646', 'Este medicamento es refrigerado, el despacho gratis no aplica y solo está disponible en las siguientes comunas: CONCHALI, ESTACION CE NTRAL, HUECHURABA, INDEPENDENCIA, LA CISTERNA, LA GRANJA, LA FLORIDA, LA REINA, LAS CONDES, LO PRADO, MACUL, NUNOA, PEDRO AGUIRRE CERDA, PENALOLEN, PROVIDENCIA, QUINTA NORMAL, RECOLETA, SAN MIGUEL, SAN JOAQUIN, SANTIAGO, VITACURA y LO BARNECHEA. La cantidad a despachar será revisada por el Químico Farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $220.990 Cada solución inyectable contiene Erenumab. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=B-2831/20 Este medicamento no tiene servicio de traslado con Shipex Express, si desea concretar su recibo, lo puede hacer a través de Shipex o retirarlo en nuestra sucursal. Nota: Para este medicamento de alto valor no será válido ningún cupón de descuento, aunque por sistema se reflejan dichos descuentos. Si el usuario utiliza algún cupón, el equipo de servicio al cliente lo contactará posteriormente para confirmar si quiere pagar la diferencia o anular la compra.', 'Solución Inyectable Jeringa Precargada', NULL),
  ('Neurexan x 50 comprimidos sublinguales', 'farmex', '1672513224756', 'Neurexan es un medicamento homeopático indicado para el tratamiento de síntomas relacionados con el estrés, la ansiedad y el insomnio. Su fórmula combina ingredientes naturales que promueven la calma y mejoran la calidad del sueño sin efectos sedantes fuertes. Ideal para personas que buscan una solución suave y natural para manejar el estrés diario. INFORMACIÓN TÉCNICA Principios Activos : Aconitum napellus, Bryonia, Kalium phosphoricum, Passiflora incarnata. Forma Farmacéutica : Comprimidos sublinguales. Dosis por Aplicación : 1-2 comprimidos según necesidad, dejando disolver bajo la lengua. Cantidad por envase : Varía según presentación (generalmente 40 o 80 comprimidos). Presentación (Forma Farmacéutica y Dosis): Este producto tiene una presentación en formato de comprimidos sublinguales, diseñados para disolverse rápidamente bajo la lengua. Cada envase contiene 40 o 80 comprimidos, proporcionando un suministro adecuado para el manejo de síntomas de estrés, ansiedad o insomnio. CONDICIONES DE ALMACENAMIENTO Almacenar a temperatura ambiente (entre 15°C y 25°C). Mantener en un lugar seco y protegido de la luz solar directa. Cerrar bien el envase después de cada uso. Mantener lejos del alcance de los niños. Nombre del Producto : Neurexan. Condición de Venta : Venta libre. NOTAS ADICIONALES Uso recomendado : Tomar 1-2 comprimidos sublinguales 3 veces al día, dejándolos disolver bajo la lengua. Puede aumentarse la frecuencia en casos de estrés agudo. Importante : No exceder la dosis recomendada. Consulte a su médico antes de usarlo si está embarazada, lactando o tomando otros medicamentos. EFECTOS COLATERALES Neurexan generalmente es bien tolerado cuando se usa correctamente. Sin embargo, pueden ocurrir reacciones adversas muy raras como: Reacciones alérgicas locales (picazón o enrojecimiento en la boca). Sensación de hormigueo leve tras la disolución. Si experimenta algún síntoma persistente o grave, suspenda el uso y consulte a su médico. BENEFICIOS PRINCIPALES Neurexan ofrece múltiples beneficios para el manejo del estrés, ansiedad e insomnio: Alivio del estrés : Ayuda a calmar los nervios y reducir la sensación de tensión emocional. Mejora del sueño : Promueve un descanso reparador sin causar somnolencia residual. Acción suave : Su formulación homeopática lo hace adecuado para uso prolongado sin efectos secundarios significativos. Fácil administración : Los comprimidos sublinguales permiten una absorción rápida y eficiente. Solución natural : Ingredientes derivados de plantas y minerales, ideales para quienes prefieren alternativas no convencionales.', 'comprimidos sublinguales', NULL),
  ('Ripol 50 mg x 5 comprimidos', 'farmex', '1536262438964', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $598 C ada comprimido contiene: Sildenafil 50 mg. Indicación: Tratamiento de la disfunción eréctil. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-11957/22', 'comprimidos', NULL),
  ('Kitadol 500 mg x 24 comprimidos', 'farmex', '1439939788852', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $41 Cada comprimido contiene: Paracetamol 500 mg. Indicaciones: Tratamiento sintomático de estados dolorosos y febriles. Dolor de cabeza, de dientes, dolores musculares. Alivio de los malestares de la gripe y el resfrío. Indicado en personas con intolerancia o alergia al ácido acetilsalicílico. Posología: Comprimidos Adultos: 1-2 comprimidos, puede repetirse cada 4 horas, hasta 4 a 5 veces /día. Máximo: 5 dosis al día (máximo 4 g diarios en adultos y 2.5 g en niños de 6 a 12 años). Contraindicaciones: Hipersensibilidad al paracetamol. Insuficiencia hepática. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-494/23', 'comprimidos', NULL),
  ('Alopek Solución Tópica 5 % x 60 mL', 'farmex', '1538812477492', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado Precio por producto fraccionado por cada 100 mL: $31.650 C ada 100 mL de solución contiene: Minoxidil 5.0 g. Indicación: Tratamiento de la alopecía androgenética. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-22175/20', 'mL', NULL),
  ('Paracetamol 500 mg x 16 comprimidos', 'farmex', '4778842882128', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $49 C ada comprimido recubierto contiene 500 mg de paracetamol Indicaciones: Dolor leve a moderado. Estados febriles. Intolerancia a salicilatos. Posología: Adultos: 1-4 g/día cada 4-6 horas (dosis máxima 4 g/día). Contraindicaciones: Hipersensibilidad al paracetamol. Insuficiencia hepática. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: http://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-4001/15', 'comprimidos', NULL),
  ('Loceryl Laca x 1,25 mL', 'farmex', '1646998585396', 'Loceryl Laca es un tratamiento antimicótico tópico indicado para infecciones por hongos en las uñas. Su fórmula con amorolfina actúa directamente sobre el área afectada, eliminando el hongo y previniendo su reaparición. Ideal para tratar onicomicosis leves o moderadas de manera efectiva y segura. INFORMACIÓN TÉCNICA Principio Activo : Amorolfina (clorhidrato) Forma Farmacéutica : Solución tópica (laca) Dosis por Aplicación : 1 aplicación semanal (o según indicación médica) Cantidad por envase : 1,25 mL Presentación (Forma Farmacéutica y Dosis): Este producto tiene una presentación en formato de solución tópica (laca), con una concentración de amorolfina al 5%. Cada envase contiene 1,25 mL, suficiente para múltiples aplicaciones semanales durante el tratamiento. CONDICIONES DE ALMACENAMIENTO Almacenar a temperatura ambiente (entre 15°C y 25°C). Mantener en un lugar seco y protegido de la luz solar directa. Cerrar bien el envase después de cada uso. Mantener lejos del alcance de los niños. Nombre del Producto : Loceryl Laca 5% (Amorolfina). Condición de Venta : Venta bajo receta médica. NOTAS ADICIONALES Uso recomendado : Aplicar directamente sobre la uña afectada, siguiendo las instrucciones del médico o profesional de la salud. Importante : No utilizar en uñas sanas o sin infección confirmada. Realice una prueba de sensibilidad antes del primer uso. Consulte a su médico si está embarazada, lactando o tiene alguna condición médica especial. EFECTOS COLATERALES Loceryl Laca generalmente es bien tolerada cuando se usa correctamente. Sin embargo, pueden ocurrir reacciones adversas locales como: Irritación leve en la piel o alrededor de la uña. Enrojecimiento o picazón en el área aplicada. Sensación de ardor o sequedad tras la aplicación. Si experimenta algún síntoma persistente o grave, suspenda el uso y consulte a su médico. BENEFICIOS PRINCIPALES Loceryl Laca ofrece múltiples beneficios para el tratamiento de infecciones por hongos en las uñas: Acción antimicótica : Elimina eficazmente los hongos responsables de la onicomicosis. Fácil aplicación : Su formato en laca permite una aplicación precisa y cómoda. Prevención de recurrencia : Penetra profundamente en la uña, evitando que el hongo vuelva a desarrollarse. Tratamiento seguro : Fórmula diseñada para minimizar irritaciones y maximizar resultados. Resultados visibles : Mejora gradualmente el aspecto y salud de las uñas afectadas.', 'mL', NULL),
  ('Tadavitae 5 mg x 28 comprimidos', 'farmex', '7541734080694', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $785 Cada comprimido recubierto contiene: Tadalafilo 5 mg. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-25255/20', 'comprimidos', NULL),
  ('Trimebutino Maleato 100 mg x 20 comprimidos', 'farmex', '4656430940240', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $50 Cada comprimido contiene: Trimebutina Maleato 100 mg. Indicación: Síndrome de intestino irritable (colopatías funcionales, colon irritable, colon inestable, colon espástico) y sus manifestaciones. Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-12361/22', 'comprimidos', NULL),
  ('Taldus 20 mg x 4 comprimidos', 'farmex', '4471162404944', 'Recupera la Confianza y el Bienestar en tu Vida Íntima 🔥 Mejora tu desempeño y calidad de vida con Taldus 20 mg x 4 comprimidos . Este medicamento está diseñado para el tratamiento de la disfunción eréctil en hombres, ayudando a obtener y mantener una erección adecuada para una actividad sexual satisfactoria. Gracias a su principio activo, el Tadalafilo , ofrece una ventana de acción prolongada, permitiendo una mayor espontaneidad en el encuentro de pareja bajo una estimulación sexual previa. Beneficios Clave Efecto Prolongado: Conocido por su extensa duración de acción en comparación con otros tratamientos similares. Mayor Espontaneidad: Su efecto permite una respuesta natural ante la estimulación sexual en un margen de tiempo amplio. Dosis Eficaz: Cada comprimido contiene 20 mg, la dosis estándar para una respuesta terapéutica óptima. Calidad Garantizada: Producto desarrollado bajo los estándares de eficacia y seguridad correspondientes. Datos Esenciales Principio Activo: Tadalafilo 20 mg por cada comprimido recubierto. Forma Farmacéutica: Comprimidos recubiertos. Dosis por Forma Farmacéutica: 20 mg. Cantidad por Envase: 4 comprimidos. Laboratorio: Synthon. Precio por Producto Fraccionado: $3.998 Condiciones de Almacenamiento Almacenar a temperatura ambiente (no más de 25°C o 30°C según envase). Mantener en un lugar fresco, seco y protegido de la luz directa. Mantener fuera del alcance de los niños. Nombre del Producto Taldus 20 mg x 4 comprimidos (Laboratorio Synthon). Condición de Venta Venta con receta médica simple. Efectos Colaterales El uso de Tadalafilo puede presentar algunos efectos secundarios leves o moderados, tales como: Dolor de cabeza o mareos. Enrojecimiento facial o congestión nasal. Malestar estomacal o indigestión (dispepsia). Dolor muscular o de espalda tras algunas horas de la toma. Si experimenta una erección que dura más de 4 horas o pérdida repentina de la visión o audición, busque atención médica de inmediato. Contraindicaciones Uso de Nitratos: Contraindicado de forma absoluta en pacientes que estén tomando cualquier forma de nitratos (medicamentos para el corazón o dolor de pecho), ya que puede causar una caída peligrosa de la presión arterial. No utilizar en caso de hipersensibilidad al Tadalafilo. Contraindicado en pacientes con enfermedades cardíacas graves donde la actividad sexual no es aconsejable. No recomendado en personas con insuficiencia hepática o renal severa sin previa evaluación médica específica. Notas Adicionales Uso recomendado: Debe tomarse al menos 30 a 60 minutos antes de la actividad sexual prevista. Solo funciona bajo estimulación sexual; no es un afrodisíaco. No se recomienda el consumo excesivo de alcohol, ya que puede dificultar la erección y aumentar el riesgo de mareos.', 'comprimidos', NULL),
  ('Esomeprazol 40 mg x 30 comprimidos', 'farmex', '1655877206068', 'La cantidad a despachar será revisada por el químico farmacéutico según tratamiento adecuado. Precio por producto fraccionado: $155 Cada comprimido con recubrimiento entérico contiene: Esomeprazol 40 mg. Indicación: Se utiliza en el Reflujo gastroesofágico (RGE): tratamiento de la esofagitis por reflujo erosiva; Tratamiento preventivo a largo plazo de recaídas de esofagitis cicatrizada; Tratamiento sintomático del reflujo gastroesofágico (RGE). Para mayor información del medicamento (condición de almacenamiento u otro) dirigirse a: https://registrosanitario.ispch.gob.cl/Ficha.aspx?RegistroISP=F-23524/22', 'comprimidos', NULL),
  ('Rosuvastatina 10 mg x 30 comprimidos', 'farmex', '7077961597110', 'Tu Aliado Diario para Controlar el Colesterol y Proteger tu Corazón ❤️ Descubre una solución confiable desarrollada por Laboratorio Chile para el tratamiento de la hipercolesterolemia en adultos, adolescentes y niños a partir de 6 años. Con Rosuvastatina 10 mg , este medicamento ayuda a reducir los niveles elevados de colesterol LDL ("malo") y triglicéridos, mientras aumenta el colesterol HDL ("bueno"). Ideal para quienes buscan prevenir enfermedades cardiovasculares y mantener un estilo de vida saludable bajo supervisión médica. INFORMACIÓN TÉCNICA Principio Activo : Rosuvastatina 10 mg. Forma Farmacéutica : Comprimidos. Dosis por Forma Farmacéutica : 1 comprimido (según indicación médica). Cantidad por Envase : 30 comprimidos. Condiciones de Almacenamiento Almacenar a temperatura ambiente (entre 15°C y 25°C). Proteger de la luz solar directa y la humedad. Mantener fuera del alcance de los niños. Nombre del Producto Rosuvastatina 10 mg x 30 comprimidos (Laboratorio Chile). Condición de Venta Venta con receta médica retenida. Notas Adicionales Uso recomendado : La dosis diaria será determinada por tu médico, generalmente 1 comprimido al día, preferiblemente a la misma hora. Modo de Administración : Tragar el comprimido entero con agua, con o sin alimentos. Importante : Este producto debe usarse bajo supervisión médica estricta. Es esencial combinar el tratamiento con una dieta equilibrada, ejercicio regular y hábitos saludables para obtener los mejores resultados. Efectos Colaterales Generalmente bien tolerado, pero pueden ocurrir efectos adversos como: Dolor de cabeza o mareos. Molestias musculares o debilidad. En casos raros, problemas hepáticos o musculares graves. Si experimentas algún síntoma persistente o grave, suspende el uso y consulta inmediatamente a tu médico. Beneficios Clave Este medicamento ofrece múltiples ventajas para el control del colesterol: Reducción Eficaz del Colesterol LDL : Ayuda a disminuir los niveles de colesterol "malo" en sangre. Protección Cardiovascular : Reduce el riesgo de enfermedades cardíacas y accidentes cerebrovasculares. Fácil de Usar : Presentación en comprimidos de fácil administración, ideal para incorporar en tu rutina diaria. Compromiso Laboratorio Chile : Desarrollado por un laboratorio líder en soluciones accesibles y confiables para toda la familia. Contraindicaciones No use si tiene hipersensibilidad conocida a la Rosuvastatina u otros componentes del producto. Evite su uso si tiene enfermedad hepática activa, insuficiencia renal severa o está embarazada/lactando. Consulte a su médico antes de usarlo si toma otros medicamentos que afecten el hígado o los músculos.', 'comprimidos', NULL),
  ('Traumeel S x 50 comprimidos', 'farmex', '1672782839860', 'Traumeel S es un medicamento homeopático utilizado para el tratamiento de diversas afecciones inflamatorias y traumáticas. Actúa reduciendo el dolor, la inflamación y promoviendo la recuperación en lesiones agudas y crónicas. Es ideal para personas que buscan una solución natural para tratar traumatismos, dolencias articulares y otras condiciones inflamatorias. INFORMACIÓN TÉCNICA Principios Activos : Arnica montana D2 15 mg Calendula officinalis D2 15 mg Hamamelis virginiana D2 15 mg Achillea millefolium D3 15 mg Atropa belladonna D4 75 mg Aconitum napellus D3 30 mg Mercurius solubilis Hahnemannii D8 30 mg Hepar sulfuris calcareum D8 30 mg Chamomilla recutita D3 24 mg Symphytum officinale D8 24 mg Bellis perennis D2 6 mg Echinacea angustifolia D2 6 mg Echinacea purpurea D2 6 mg Hypericum perforatum D2 3 mg Forma Farmacéutica : Comprimidos sublinguales. Dosis por Forma Farmacéutica : 1 comprimido sublingual. Cantidad por envase : 50 comprimidos. Precio por producto fraccionado : $269. Este producto se presenta en comprimidos sublinguales, diseñados para disolverse lentamente bajo la lengua. El envase contiene 50 comprimidos, lo que permite un suministro adecuado para el tratamiento de diversas condiciones agudas y crónicas. Condiciones de Almacenamiento Almacenar a no más de 25°C. Mantener en un lugar fresco, seco y oscuro. Evitar la exposición directa a la luz solar. Mantener lejos del alcance de los niños. Nombre del Producto Traumeel S x 50 comprimidos. Condición de Venta Venta libre. Notas Adicionales Uso recomendado : En casos generales: Dejar disolver lentamente bajo la lengua 1 comprimido 3 veces al día. En casos agudos: 1 comprimido cada 15 minutos por 2 horas (como máximo). Importante : No administrar en caso de antecedentes de alergia o hipersensibilidad a este producto o a alguno de sus componentes. No utilizar en caso de enfermedades sistémicas como tuberculosis, leucosis, colagenosis, esclerosis múltiple, pacientes portadores de VIH o los que han desarrollado SIDA y en otras enfermedades autoinmunes. Consulte a su médico antes de usarlo si está embarazada, lactando o tomando otros medicamentos. Efectos Colaterales Generalmente bien tolerado, pero pueden ocurrir efectos adversos leves como: Reacciones alérgicas locales o sistémicas en casos sensibles a alguno de los componentes. Irritación o malestar leve en la boca debido a la disolución sublingual. Si experimenta algún síntoma persistente, suspenda el uso y consulte a su médico. Beneficios Principales Traumeel S ofrece múltiples beneficios para el tratamiento de diversas condiciones: Reducción del dolor e inflamación : Ideal para traumatismos como esguinces, contusiones, hematomas, luxaciones y fracturas. Recuperación postquirúrgica : Ayuda a reducir edemas y tumefacciones postraumáticas o postquirúrgicas. Tratamiento de afecciones articulares : Eficaz en tendinitis, artritis, artrosis y otras dolencias reumáticas. Apoyo en lesiones deportivas : Alivia síntomas asociados con tendinosis, epicondilitis, bursitis y periartritis. Acción antiinflamatoria : Combate procesos inflamatorios agudos y crónicos, incluyendo gingivitis, paradontitis y estiloiditis.', 'comprimidos', NULL),
