-- ============================================================================
-- VERIFICACION
-- ============================================================================
-- 1) Contar los 50 medicamentos source='farmex'
select count(*) as medications_farmex from public.medications where source = 'farmex';

-- 2) Confirmar que existe una sola farmacia demo
select count(*) as farmacias_demo from public.pharmacies where source = 'farmex_demo' and external_id = 'farmex-guardia-vieja-80';

-- 3) Confirmar que existen 50 registros de stock asociados
select count(*) as stock_demo from public.pharmacy_stock where source = 'farmex_demo';

-- 4) Confirmar que todas las cantidades estan entre 1 y 20
select count(*) as cantidades_fuera_de_rango from public.pharmacy_stock where source = 'farmex_demo' and (quantity is null or quantity < 1 or quantity > 20);

-- 5) Confirmar que no existen duplicados por source/external_id (medicamentos)
select source, external_id, count(*) as dup_count from public.medications where source = 'farmex' group by source, external_id having count(*) > 1;

-- 6) Mostrar nombres, precios y cantidades cargadas
select m.name, s.price, s.quantity
from public.pharmacy_stock s
join public.medications m on m.id = s.medication_id
where s.source = 'farmex_demo'
order by m.name;
